#include<bits/stdc++.h>
using namespace std;
uint8_t buf[1<<20],*p1,*p2;
#define gc() (p1 == p2 && (p2 = (p1 = buf) + fread(buf,1,1<<20,stdin)),*p1++)
inline int read(){
    int x = 0,f = 1;
    char ch = gc();
    while(ch < '0' || ch > '9'){
        if (ch == '-')f = -1;
        ch = gc();
    }
    while(ch >= '0' && ch <= '9'){
        x = (x<<1) + (x<<3) + (ch - '0');
        ch = gc();
    }
    return x * f;
}
inline void write(int x){
    if (x < 0)x *= -1,putchar('-');
    if (x > 9)write(x / 10);
    putchar(x % 10 + '0');
    return ;
}
signed main(){
    int x = read();
    write(x);
    return 0;
}

