欧拉筛
#include<bits/stdc++.h>
using namespace std;
const int N=1e5+5;
int n,tot,zx[N];
//zx[i]保存 i 的最小质因数
vector<int> isp(N,true);
vector<int> pri;
inline void ols(){
    for(int i = 2;i <= n;i ++){
        if (isp[i]){
            tot ++;
            pri.push_back(i);
            zx[i] = i;
        }
        for(auto j : pri){
            if (j > n / i)break;//防止 i * j 炸 int
            isp[i * j] = false;
            zx[i * j] = j;
            if (i % j == 0)break;//每次只用最小质因子筛
        }
    }
}
signed main(){
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);
    cin >> n;
    isp[0] = isp[1] = false;
    isp[2] = true;
    ols();
    for(auto i : pri){
        cout << i << " ";
    }
    cout << "\n";
    for(int i = 2;i <= n;i ++){
        cout << zx[i] << " ";
    }
    return 0;
}

