归并排序
#include<bits/stdc++.h>
using namespace std;
int n;
int a[100005];
int b[100005];
void merge(int l,int r,int m){
	int i = l,j = m + 1;
	int cnt = l;
	while(i <= m and j <= r){
		if (a[i] < a[j]){
			b[cnt] = a[i];
			i ++;
		}else{
			b[cnt] = a[j];
			j ++;
		}
		cnt ++;
	}
	while(i <= m){
		b[cnt] = a[i];
		i ++;
		cnt ++;
	}
	while(j <= r){
		b[cnt] = a[j];
		j ++;
		cnt ++;
	}
	for(int k = l;k <= r;k ++){
		a[k] = b[k];
	}
}
void bsort(int l,int r){
	if (l >= r)return;
	int m = (l + r) / 2;
	bsort(l,m);
	bsort(m + 1,r);
	merge(l,r,m);//合并左右部分 
}
int main(){
	cin >> n;
	for(int i = 1;i <= n;i ++){
		cin >> a[i];
	}
	bsort(1,n);
	for(int i = 1;i <= n;i ++){
		cout << a[i] << " ";
	}
    return 0;
}

