#include<bits/stdc++.h>
using namespace std;
struct node{
	int y,v;
	node(int _y,int _v){
		y = _y,v = _v;
	}
};
vector<node>edge[5003];
int n,m,k,dist[5003];
bool b[5003];
inline void dijkstra(int s,int t){
	memset(b,false,sizeof(b));
	memset(dist,127,sizeof(dist));
	dist[s]=0;
	for(;;){
		int x = -1;
		for(int i = 1;i <= n;i ++){
			if (!b[i] and dist[i] < 1 << 30 ){
				if (x == -1 or dist[i] < dist[x]){
					x = i;
				}
			}
		}
		if (x == t or x == -1){
			break;
		}
		b[x] = true;
		for(auto i : edge[x]){
			dist[i.y] = min(dist[i.y],dist[x] + i.v);
		}

	}
	if (dist[t] < 1 << 30){
		cout << dist[t] << "\n";
	}else{
		cout << -1 << "\n";
	}
}
int main(){
	cin >> n >> m >> k;
	for(int i = 1;i <= m;i ++){
		int x,y,z;
		cin >> x >> y >> z;
		edge[x].push_back(node(y,z));
	}
	for(int i = 1;i <= k;i ++){
		int s,t;
		cin >> s >> t;
		dijkstra(s,t);
	}
	return 0;
}

dijkstra 堆优化
#include<bits/stdc++.h>
using namespace std;
const int N = 1e5 + 5;
int n, q;
struct node{ int to, d; };
vector<node> e[N];
inline void dijkstra(int s, int t){
    static int  dist[N];
    static bool vis[N];
    memset(dist, 0x3f, sizeof(int ) * (n + 1));   
    memset(vis , 0   , sizeof(bool) * (n + 1));
    priority_queue<pair<int,int>,vector<pair<int,int>>,greater<pair<int,int>>> pq;
    dist[s] = 0;
    pq.push({0, s});
    while(!pq.empty()){
        pair<int,int> p = pq.top(); pq.pop();
        int d = p.first, u = p.second;
        if(vis[u]) continue;      
        vis[u] = true;
        if(u == t) break;         
        for(auto &nx : e[u]){
            int v = nx.to, w = nx.d;
            if(dist[v] > d + w){  
                dist[v] = d + w;
                pq.push({dist[v], v});
            }
        }
    }
    cout << dist[t] << '\n';
}
signed main(){
    ios::sync_with_stdio(false);
    cin.tie(0);
    cin >> n >> q;
    for(int i = 1; i < n; i++){
        int u, v, w;
        cin >> u >> v >> w;
        e[u].push_back({v, w});
        e[v].push_back({u, w});
    }
    while(q--){
        int from, to;
        cin >> from >> to;
        dijkstra(from, to);
    }
    return 0;
}

